"""Fixtures generated by actual published tags, not invented schema version numbers."""
import json
import tempfile
import unittest
from contextlib import closing
from pathlib import Path

from colegio.backup_inspection import probe_backup,file_hash
from colegio.db import connect,charges
from colegio.server import open_school
from tests.restore_helpers import approved_restore


class HistoricalRestoreTests(unittest.TestCase):
    def test_published_versions_restore_then_existing_migrations_preserve_money(self):
        root=Path(__file__).parent/'fixtures/restore'
        manifests=json.loads((root/'manifest.json').read_text())
        self.assertEqual({m['tag'] for m in manifests},{'desktop-1.0.4','desktop-1.0.6','desktop-1.0.7','desktop-1.0.13'})
        for metadata in manifests:
            with self.subTest(tag=metadata['tag']),tempfile.TemporaryDirectory() as directory:
                source=root/metadata['filename'];before=file_hash(source)
                self.assertEqual(before,metadata['sha256'])
                summary=probe_backup(source)
                self.assertEqual(summary['schema'],metadata['schema'])
                target=approved_restore(source,directory)
                self.assertEqual(probe_backup(target)['schema'],13,'La candidata se migra antes de publicarse')
                with open_school(target,0):pass # Reuse the existing historical migrations unchanged.
                with closing(connect(target)) as db:
                    self.assertEqual(db.execute('PRAGMA user_version').fetchone()[0],13)
                    self.assertEqual(db.execute('PRAGMA integrity_check').fetchone()[0],'ok')
                    self.assertFalse(db.execute('PRAGMA foreign_key_check').fetchone())
                    self.assertEqual(db.execute('SELECT COUNT(*) FROM payments').fetchone()[0],1)
                    self.assertEqual(db.execute('SELECT amount FROM payments').fetchone()[0],5000)
                    self.assertEqual(sum(c['balance'] for c in charges(db)),5000)
                    self.assertGreater(int(db.execute("SELECT value FROM settings WHERE key='id_floor_payments'").fetchone()[0]),0)
                self.assertEqual(file_hash(source),before)
